import { beforeAll, describe, expect, it } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from '../src/app.js'
import { Post } from '../app/Models/Post.js'
import { User } from '../app/Models/User.js'

describe('scheduled posts', () => {
  let http: TestApp
  let author: any
  let other: any
  let future: any
  let past: any

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
    const stamp = Date.now()
    author = await User.forceCreate({ name: 'A', email: `a${stamp}@x.test`, passwordHash: 'x' })
    other = await User.forceCreate({ name: 'B', email: `b${stamp}@x.test`, passwordHash: 'x' })
    future = await Post.forceCreate({
      title: 'Soon sched',
      excerpt: 'e',
      body: 'b',
      authorId: author.id,
      publishedAt: new Date(Date.now() + 86_400_000).toISOString(),
    })
    past = await Post.forceCreate({
      title: 'Past sched',
      excerpt: 'e',
      body: 'b',
      authorId: author.id,
      publishedAt: new Date(Date.now() - 86_400_000).toISOString(),
    })
  })

  it('hides a scheduled post from guests and others, shows it to the author', async () => {
    await http.get(`/posts/${future.id}`).assertNotFound()
    await http.actingAs(other).get(`/posts/${future.id}`).assertNotFound()
    await http.actingAs(author).get(`/posts/${future.id}`).assertOk()
    await http.get(`/posts/${past.id}`).assertOk()

    const guest = await http.get('/posts')
    expect(JSON.stringify(await guest.response.text())).not.toContain('Soon sched')
    const mine = await http.actingAs(author).get('/posts')
    expect(await mine.response.text()).toContain('Soon sched')
  })

  it('keeps scheduled posts out of search', async () => {
    const res = await http.query('/posts/search', { keywords: ['sched'] })
    const text = await res.response.text()
    expect(text).not.toContain('Soon sched')
    expect(text).toContain('Past sched')
  })
})
E
